  void RenderOfficial(){if(softwarePage){RenderSoftware();return;}if(officialStatus==null||officialStatus.IsDisposed)return;officialCheck.Enabled=!busy;officialCancel.Enabled=busy&&onlineCancellation!=null;officialCancel.Visible=onlineCancellation!=null;officialNotes.Enabled=!busy&&officialRelease!=null;bool newer=officialRelease!=null&&OfficialUpdates.IsNewer(officialRelease,settings.CurrentFolder);officialDownload.Enabled=!busy&&newer;officialDownload.Text=officialRelease!=null&&downloadedTag==officialRelease.Tag&&File.Exists(officialArchive)?"安装已下载版本":"下载并更新";if(officialRelease==null){officialStatus.Text="尚未检查官方版本";officialStatus.ForeColor=Muted;return;}Version current=OfficialUpdates.CurrentVersion(settings.CurrentFolder);officialStatus.Text=newer?"可用版本  "+officialRelease.Version+"  ·  "+(officialRelease.Size/1024d/1024d).ToString("F1")+" MB":"当前版本已是最新  ·  "+(current==null?officialRelease.Version.ToString():current.ToString());officialStatus.ForeColor=newer?Ink:Green;}
  async void CheckOfficial(){if(busy)return;onlineCancellation=new CancellationTokenSource();SetBusy(true);officialStatus.Text="正在检查官方版本…";officialStatus.ForeColor=Muted;try{var release=await Task.Run(()=>OfficialUpdates.GetLatest(onlineCancellation.Token));if(officialRelease!=null&&officialRelease.Tag!=release.Tag){officialArchive="";downloadedTag="";}officialRelease=release;officialArchive=await Task.Run(()=>DownloadCache.Find(Path.Combine(Core.DataDir,"downloads"),release));downloadedTag=String.IsNullOrEmpty(officialArchive)?"":release.Tag;Log("官方最新正式版："+release.Tag+" / "+release.Name);}catch(OperationCanceledException){Log("已取消版本检查。");downloadStatus.Text="检查已取消";}catch(Exception e){Log("检查失败："+e.Message);downloadStatus.Text=e.Message;officialRelease=null;}finally{onlineCancellation.Dispose();onlineCancellation=null;SetBusy(false);}}
  async void DownloadOfficial(){if(busy||officialRelease==null||!OfficialUpdates.IsNewer(officialRelease,settings.CurrentFolder))return;var release=officialRelease;var session=new ModDownloadSession(Bridge.GameRunning());bool downloaded=false;onlineCancellation=new CancellationTokenSource();SetBusy(true);downloadStatus.Text="正在准备下载…";try{if(downloadedTag==release.Tag&&File.Exists(officialArchive)){await Task.Run(()=>OfficialUpdates.VerifyArchive(release,officialArchive));}else{downloadProgress.Value=0;Log("下载官方完整包："+release.Name);var progress=new Progress<DownloadProgress>(p=>{if(onlineCancellation!=null&&downloadProgress!=null&&!downloadProgress.IsDisposed){downloadProgress.Value=p.Percent;downloadStatus.Text=p.Percent+"%  ·  "+(p.Received/1024d/1024d).ToString("F1")+" / "+(p.Total/1024d/1024d).ToString("F1")+" MB  ·  "+(p.BytesPerSecond/1024d/1024d).ToString("F2")+" MB/s";}});officialArchive=await Task.Run(()=>OfficialUpdates.Download(release,Path.Combine(Core.DataDir,"downloads"),onlineCancellation.Token,p=>((IProgress<DownloadProgress>)progress).Report(p),null));downloadedTag=release.Tag;await Task.Run(()=>DownloadCache.Save(Path.Combine(Core.DataDir,"downloads"),release,officialArchive));}onlineCancellation.Token.ThrowIfCancellationRequested();downloaded=true;downloadProgress.Value=100;downloadStatus.Text="下载完成  ·  SHA256 校验通过";Log("完整包已下载并通过 SHA256 校验。");}catch(OperationCanceledException){downloadStatus.Text="下载已取消，可重新下载。";Log("下载已取消，现有安装未变。");}catch(Exception e){downloadStatus.Text=e.Message;Log("下载未完成："+e.Message);officialArchive="";downloadedTag="";}finally{onlineCancellation.Dispose();onlineCancellation=null;SetBusy(false);}if(!downloaded)return;if(!session.CanInstallAutomatically(Bridge.GameRunning())){downloadStatus.Text="已下载并校验  ·  退出游戏后点击“安装已下载版本”";Log("游戏正在运行，安装包已保留，等待你退出游戏后安装。");return;}UpdateArchive(officialArchive);}
