  void ShowReleaseNotes(OfficialRelease release){if(busy||release==null)return;using(var dialog=new Form{Text="官方更新说明  ·  "+release.Tag,Size=new Size(780,620),StartPosition=FormStartPosition.CenterParent,Font=Font,BackColor=Theme.Surface,MinimizeBox=false}){var text=new TextBox{ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,BackColor=Theme.Surface,ForeColor=Ink,Text=release.Tag+"  /  "+release.PublishedUtc.ToLocalTime().ToString("yyyy-MM-dd")+Environment.NewLine+Environment.NewLine+release.Notes};dialog.Controls.Add(text);var footer=new Panel{Dock=DockStyle.Bottom,Height=70,BackColor=Theme.Surface};footer.Controls.Add(ButtonAt("打开官方发布页",24,12,220,44,false,()=>{try{Process.Start(new ProcessStartInfo(release.PageUrl){UseShellExecute=true});}catch(Exception e){Error(e.Message);}}));footer.Controls.Add(ButtonAt("关闭",530,12,170,44,true,()=>dialog.Close()));dialog.Controls.Add(footer);dialog.ShowDialog(this);}}
  void OpenFolder(string p){try{if(!Directory.Exists(p))throw new Exception("文件夹尚未创建。");Process.Start("explorer.exe",Core.Quote(p));}catch(Exception ex){Error(ex.Message);}}
  async void StopBridge(){if(busy)return;SetBusy(true);try{await Task.Run(()=>Bridge.Stop(settings.CurrentFolder));SyncContext();connectivity.RecordCheck(new CheckResult{Error="桥已手动停止。"},DateTime.UtcNow);RenderChecks();Log("当前版本的桥已停止。");}catch(Exception ex){Error(ex.Message);}finally{SetBusy(false);}}
  void SyncContext(){string port;try{port=Bridge.Port(settings.CurrentFolder).ToString();}catch{port="invalid";}string key=(settings.GameRoot+"|"+settings.CurrentFolder+"|"+port).ToUpperInvariant();if(key!=connectivity.Context)installation=null;connectivity.ChangeContext(key);}
  void RefreshLaunch(){bool running=Bridge.GameRunning();if(launch!=null&&!launch.IsDisposed)launch.Text=running?"检查运行状态  →":"检查并启动游戏  →";}
  async void PollBridge(){if(busy||monitoring||detecting||IsDisposed)return;monitoring=true;try{SyncContext();long revision=connectivity.Revision;string folder=settings.CurrentFolder;var result=await Task.Run(()=>Bridge.Probe(folder));if(IsDisposed||Disposing||busy)return;SyncContext();if(connectivity.ApplyProbe(result,revision,DateTime.UtcNow)){RenderChecks();RefreshLaunch();}}catch(Exception ex){if(!IsDisposed&&!Disposing)Log("状态查询未完成："+ex.Message);}finally{monitoring=false;}}
  Color StatusColor(Color color){if(Theme.IsDark)return color;if(local!=null&&local.Parent!=null&&local.Parent.BackColor==Theme.Dark){if(color==Theme.Success)return Color.FromArgb(157,219,175);if(color==Theme.Danger)return Color.FromArgb(255,156,141);return Color.FromArgb(211,222,207);}return color;}
  void RenderChecks(){if(local==null||local.IsDisposed||translation==null||translation.IsDisposed)return;DateTime now=DateTime.UtcNow;hints.SetToolTip(local,"每 15 秒刷新本地桥状态。");hints.SetToolTip(translation,"在线测试结果 10 分钟有效；桥离线或重启后需重新测试。");
   local.Text=!connectivity.Known?"○  本地桥服务    尚未检查":connectivity.LocalFresh(now)?"✓  本地桥服务    正常 · "+connectivity.ProbeUtc.ToLocalTime().ToString("HH:mm:ss"):connectivity.Local?"○  本地桥服务    状态过期，等待刷新":"✕  本地桥服务    离线 · "+connectivity.ProbeUtc.ToLocalTime().ToString("HH:mm:ss");local.ForeColor=connectivity.LocalFresh(now)?StatusColor(Theme.Success):connectivity.Known&&!connectivity.Local?StatusColor(Theme.Danger):StatusColor(Theme.Muted);
   if(connectivity.TranslationFresh(now)){translation.Text="✓  在线翻译    上次通过 "+connectivity.TranslationUtc.ToLocalTime().ToString("HH:mm:ss");translation.ForeColor=StatusColor(Theme.Success);}else{translation.ForeColor=StatusColor(Theme.Muted);translation.Text=!connectivity.LocalFresh(now)?"○  在线翻译    等待本地桥":connectivity.Translation?"○  在线翻译    上次通过 "+connectivity.TranslationUtc.ToLocalTime().ToString("HH:mm:ss")+"，需复检":!String.IsNullOrEmpty(connectivity.TranslationError)?"✕  在线翻译    最近测试未通过":"○  在线翻译    尚未测试";if(connectivity.LocalFresh(now)&&!connectivity.Translation&&!String.IsNullOrEmpty(connectivity.TranslationError))translation.ForeColor=StatusColor(Theme.Danger);}
  }
