  async void RunDiagnostics(bool restart){if(busy)return;SetBusy(true);ResetChecks();try{var report=await Task.Run(()=>{var install=Installation.Inspect(settings);CheckResult result;try{result=Recovery.Run(settings,restart,Log,LocalState,new BridgeRuntime());}catch(Exception e){result=new CheckResult{Error=e.Message};}return Tuple.Create(install,result,GameDiagnostics.Inspect(settings));});Results(report.Item2);installation=report.Item1;RenderInstallation();if(gameNotice!=null&&!gameNotice.IsDisposed)gameNotice.Text=report.Item3.Message;Log(installation.Summary);Log(report.Item3.Message);if(!String.IsNullOrEmpty(report.Item2.Error))Log(report.Item2.Error);if(!report.Item2.Local||!report.Item2.Translation)Log("检查未全部通过，请根据上方记录处理后重试。");}catch(Exception e){Log("诊断未完成："+e.Message);connectivity.RecordCheck(new CheckResult{Error=e.Message},DateTime.UtcNow);RenderChecks();}finally{SetBusy(false);}}
