   if(Bridge.GameRunning()){Error("请退出 Deadlock 后再安装；已下载的压缩包会保留。");return;}if(!importPage)ShowImportPage();SetBusy(true);ResetChecks();if(downloadStatus!=null)downloadStatus.Text="正在解压、检查并安装…";
