    SyncContext();Results(report.Check);installation=report.Installation;version.Text="当前版本  /  "+Path.GetFileName(settings.CurrentFolder);Log("新包已完整替换旧包，游戏 VPK 与加载配置检查通过。");
    if(!String.IsNullOrEmpty(report.Warning))Log(report.Warning);
    if(archive==officialArchive){try{string cache=Path.Combine(Core.DataDir,"downloads");Core.NoLinks(archive);if(Core.Under(cache,archive)){File.Delete(archive);string directory=Path.GetDirectoryName(archive);if(Directory.GetFileSystemEntries(directory).Length==0)Directory.Delete(directory);}}catch(Exception cleanup){Log("下载缓存暂未清理："+cleanup.Message);}officialArchive="";downloadedTag="";}
    if(downloadStatus!=null)downloadStatus.Text="更新完成  ·  本地桥、翻译接口与安装文件检查通过";SetBusy(false);if(String.IsNullOrEmpty(report.Warning))ConfirmLaunch();else Error(report.Warning);
   }catch(Exception ex){Log("安装未完成："+ex.Message);Results(new CheckResult{Error=ex.Message});if(downloadStatus!=null)downloadStatus.Text="安装未完成，见更新记录";SetBusy(false);Error("更新未完成。旧版本文件保留，恢复结果请看更新记录。\n\n"+ex.Message);}
   finally{if(busy)SetBusy(false);}
  }
  async void CheckLaunch(){if(busy)return;if(Bridge.GameRunning()){ShowDiagnostics();RunDiagnostics(false);return;}if(!Core.IsPackage(settings.CurrentFolder)){Error("请先导入完整压缩包，或在路径设置中选择已有版本。");return;}SetBusy(true);ResetChecks();try{installation=await Task.Run(()=>Installation.Inspect(settings));RenderInstallation();if(!installation.Ready){Log(installation.Summary);SetBusy(false);ShowDiagnostics();Error("安装检查未通过，已打开诊断页。\n\n"+installation.Summary);return;}CheckResult r=await Task.Run(()=>Recovery.Run(settings,false,Log,LocalState,new BridgeRuntime()));Results(r);SetBusy(false);if(r.Local&&r.Translation)ConfirmLaunch();else{ShowDiagnostics();Error("检查未通过，可在诊断页重试。\n\n"+r.Error);}}catch(Exception e){Results(new CheckResult{Error=e.Message});SetBusy(false);Log(e.Message);ShowDiagnostics();Error(e.Message);}}
