  [STAThread]static void Main(){try{RhineRuntime.Prepare();Run();}catch(Exception error){MessageBox.Show(error.Message,"巴别塔启动器");}}
  [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
  static void Run(){try{using(var mutex=new Mutex(false,"Local\\BabelTowerLauncher")){bool owned;try{owned=mutex.WaitOne(0,false);}catch(AbandonedMutexException){owned=true;}if(!owned){MessageBox.Show("巴别塔启动器已在运行，请切换到已有窗口。");return;}try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.ThreadException+=(s,e)=>MessageBox.Show(e.Exception.Message,"巴别塔启动器");MainWindow.RhineEnabled=true;var window=new MainWindow();window.EnableRhine();Application.Run(window);}finally{mutex.ReleaseMutex();}}}catch(Exception ex){MessageBox.Show("管理器无法打开："+ex.Message,"巴别塔启动器");}}
